#!/usr/bin/env Rscript

# ==========================================================
# Script   : objective64_post_primary_analyses.R
# Purpose  : Retain an exploratory or secondary historical analysis for transparent provenance
# Inputs   : see data/README.md and config/paths.yml
# Outputs  : historical workspace outputs; not generated by run_all.sh
# Paper    : Not a final-results workflow entry point
# Seed     : see config/params.yml
# Runtime  : not benchmarked in the public release
# Last run : see provenance/source_provenance.csv
# Source   : guarded-workspace:objective64_evidence_package_20261020/scripts/run_post_primary_objective_analyses.R
# ==========================================================
# Post-primary analyses for the frozen objective BIES rebuild.
# This script is intentionally invoked only after the 20x10 nested CV and
# the separate 499-permutation analysis have completed successfully.

suppressPackageStartupMessages({
  library(survival)
  library(glmnet)
  library(SummarizedExperiment)
})

base_dir <- normalizePath(getwd(), mustWork = TRUE)
root_dir <- normalizePath(file.path(base_dir, ".."), mustWork = TRUE)
results_dir <- file.path(base_dir, "results")
models_dir <- file.path(base_dir, "models")
logs_dir <- file.path(base_dir, "logs")
dir.create(results_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(models_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(logs_dir, recursive = TRUE, showWarnings = FALSE)

write_tsv <- function(x, path) {
  write.table(x, path, sep = "\t", quote = FALSE, row.names = FALSE, na = "NA")
}

stop_if_missing <- function(path) if (!file.exists(path)) stop("Required prerequisite is absent: ", path)
for (path in file.path(results_dir, c("NESTED_CV_FOLD_RESULTS.tsv", "NESTED_CV_REPEAT_LEVEL_RESULTS.tsv", "NESTED_CV_SELECTED_GENES.tsv", "OOF_PREDICTIONS.tsv", "PERMUTATION_SUMMARY.tsv", "OBJECTIVE_FEATURE_UNIVERSE.tsv"))) stop_if_missing(path)

make_stratified_folds <- function(status, k, seed) {
  if (length(unique(status)) != 2L) stop("Both event strata are required.")
  set.seed(seed)
  out <- integer(length(status))
  for (value in sort(unique(status))) {
    idx <- which(status == value)
    out[idx] <- sample(rep(seq_len(k), length.out = length(idx)))
  }
  out
}

spearman_row <- function(x, y, label, expected_direction = "descriptive") {
  keep <- is.finite(x) & is.finite(y)
  ct <- suppressWarnings(cor.test(x[keep], y[keep], method = "spearman", exact = FALSE))
  data.frame(
    measure = label, n = sum(keep), spearman_rho = unname(ct$estimate), p_value = ct$p.value,
    expected_direction = expected_direction, stringsAsFactors = FALSE
  )
}

cox_per_sd <- function(df, rhs, score_name = "objective_score") {
  adjustment_variables <- if (nzchar(rhs)) all.vars(stats::as.formula(paste("~", rhs))) else character()
  keep <- complete.cases(df[, unique(c("OS_time", "OS_status", score_name, adjustment_variables)), drop = FALSE])
  dat <- df[keep, , drop = FALSE]
  dat$objective_score_sd <- as.numeric(scale(dat[[score_name]]))
  form <- stats::as.formula(paste("survival::Surv(OS_time, OS_status) ~ objective_score_sd", if (nzchar(rhs)) paste0(" + ", rhs) else ""))
  fit <- survival::coxph(form, data = dat)
  sm <- summary(fit)
  i <- match("objective_score_sd", rownames(sm$coefficients))
  data.frame(
    model = if (nzchar(rhs)) rhs else "Univariable",
    n = nrow(dat), events = sum(dat$OS_status),
    HR_per_SD = sm$conf.int[i, "exp(coef)"],
    CI_lower = sm$conf.int[i, "lower .95"],
    CI_upper = sm$conf.int[i, "upper .95"],
    p_value = sm$coefficients[i, "Pr(>|z|)"],
    stringsAsFactors = FALSE
  )
}

# Locked analytical inputs.
feature <- read.delim(file.path(results_dir, "OBJECTIVE_FEATURE_UNIVERSE.tsv"), check.names = FALSE, stringsAsFactors = FALSE)
genes <- feature$gene[feature$primary_universe]
if (length(genes) != 492L || anyDuplicated(genes)) stop("Objective feature universe is not the locked 492-gene set.")
vst <- readRDS(file.path(root_dir, "results/02_WGCNA/vst_top5000.rds"))
surv <- read.csv(file.path(root_dir, "results/04_ML/features/survival_data.csv"), check.names = FALSE, stringsAsFactors = FALSE)
if (nrow(surv) != 476L || anyNA(surv$sample_id) || !all(surv$sample_id %in% colnames(vst)) || sum(surv$OS_status) != 220L) stop("Locked TCGA survival cohort mismatch.")
X <- t(vst[genes, surv$sample_id, drop = FALSE])
rownames(X) <- surv$sample_id
if (!all(is.finite(X))) stop("Non-finite values detected in locked objective matrix.")

# The full-data model is a post-performance, explanatory parameterization only.
# Its fold assignment is explicit and saved even though it does not estimate OOS performance.
final_fold_seed <- 600000L
final_fold <- make_stratified_folds(as.integer(surv$OS_status), 10L, final_fold_seed)
write_tsv(data.frame(patient_id = surv$sample_id, final_cv_fold = final_fold, final_cv_seed = final_fold_seed), file.path(results_dir, "FINAL_FULLDATA_CV_FOLD_ASSIGNMENTS.tsv"))
final_cv <- glmnet::cv.glmnet(
  x = X, y = survival::Surv(surv$OS_time, as.integer(surv$OS_status)),
  family = "cox", alpha = 0.5, nfolds = 10L, foldid = final_fold,
  type.measure = "C", standardize = TRUE
)
final_beta <- as.matrix(stats::coef(final_cv, s = "lambda.min"))[, 1]
final_nonzero <- final_beta[final_beta != 0]
final_score <- as.numeric(stats::predict(final_cv, newx = X, s = "lambda.min", type = "link"))
names(final_score) <- surv$sample_id
saveRDS(list(
  model = final_cv, lambda = as.numeric(final_cv$lambda.min), alpha = 0.5,
  standardize = TRUE, foldid = final_fold, fold_seed = final_fold_seed,
  feature_universe = genes, coefficients = final_nonzero,
  note = "Post-nested-CV full-data parameterization; not an out-of-sample performance estimate."
), file.path(models_dir, "OBJECTIVE_FINAL_MODEL.rds"))

# Primary nested-CV selection stability across all 200 independently trained outer fits.
selected <- read.delim(file.path(results_dir, "NESTED_CV_SELECTED_GENES.tsv"), check.names = FALSE, stringsAsFactors = FALSE)
stability <- lapply(genes, function(g) {
  z <- selected[selected$gene == g, , drop = FALSE]
  data.frame(
    gene = g, total_outer_models = 200L, selected_count = nrow(z),
    selection_frequency = nrow(z) / 200,
    positive_coefficient_frequency = sum(z$coefficient > 0) / 200,
    negative_coefficient_frequency = sum(z$coefficient < 0) / 200,
    median_nonzero_coefficient = if (nrow(z)) median(z$coefficient) else NA_real_,
    stringsAsFactors = FALSE
  )
})
stability <- do.call(rbind, stability)
stability <- stability[order(-stability$selection_frequency, stability$gene), , drop = FALSE]
write_tsv(stability, file.path(results_dir, "GENE_SELECTION_STABILITY_NESTEDCV.tsv"))

final_coef_out <- data.frame(
  gene = names(final_nonzero), coefficient = as.numeric(final_nonzero),
  stringsAsFactors = FALSE
)
final_coef_out$nestedCV_selection_frequency <- stability$selection_frequency[match(final_coef_out$gene, stability$gene)]
final_coef_out$legacy_F01_13 <- final_coef_out$gene %in% c("CD79A", "CD79B", "MS4A1", "IGHM", "BLK", "FCRL5", "TNFRSF17", "MZB1", "JCHAIN", "DERL3", "IGLL5", "IGKC", "CD22")
final_coef_out$legacy_BIES_4 <- final_coef_out$gene %in% c("MS4A1", "IGHM", "BLK", "JCHAIN")
final_coef_out <- final_coef_out[order(-abs(final_coef_out$coefficient), final_coef_out$gene), , drop = FALSE]
write_tsv(final_coef_out, file.path(results_dir, "OBJECTIVE_FINAL_MODEL_COEFFICIENTS.tsv"))
write_tsv(data.frame(patient_id = surv$sample_id, objective_final_linear_predictor = final_score, time = surv$OS_time, event = surv$OS_status), file.path(results_dir, "OBJECTIVE_FINAL_MODEL_SCORES.tsv"))
write_tsv(data.frame(metric = c("alpha", "lambda_rule", "lambda_min", "n_nonzero", "standardize", "final_cv_folds", "final_cv_seed"), value = c(0.5, "lambda.min", final_cv$lambda.min, length(final_nonzero), TRUE, 10, final_fold_seed)), file.path(results_dir, "OBJECTIVE_FINAL_MODEL_METADATA.tsv"))

# Cross-fitted objective LP is the sole score used in score-to-score and anchor comparisons.
oof <- read.delim(file.path(results_dir, "OOF_PREDICTIONS.tsv"), check.names = FALSE, stringsAsFactors = FALSE)
oof_mean <- aggregate(oof$oof_linear_predictor, list(patient_id = oof$patient_id), mean)
names(oof_mean)[2] <- "objective_oof_risk_score"
if (nrow(oof_mean) != 476L) stop("OOF aggregation must return one score for every patient.")
base <- surv
base$objective_score <- oof_mean$objective_oof_risk_score[match(base$sample_id, oof_mean$patient_id)]
if (anyNA(base$objective_score)) stop("OOF score alignment failed.")

# Legacy inputs are loaded only at this post-primary comparison stage.
legacy <- read.csv(file.path(root_dir, "results/04_ML/models/bcell_lasso_score_tcga.csv"), stringsAsFactors = FALSE)
legacy <- legacy[match(base$sample_id, legacy$sample_id), , drop = FALSE]
if (anyNA(legacy$sample_id)) stop("Legacy BIES score does not align to locked TCGA survival cohort.")
legacy_fit <- survival::coxph(survival::Surv(legacy$OS_time, legacy$OS_status) ~ legacy$risk_score)
legacy_beta <- unname(stats::coef(legacy_fit)[1])
legacy_transform <- if (legacy_beta >= 0) 1 else -1
base$legacy_risk_score_aligned <- legacy_transform * legacy$risk_score
legacy_sp <- spearman_row(base$objective_score, base$legacy_risk_score_aligned, "Objective OOF risk score versus risk-aligned legacy BIES", "same risk orientation")
legacy_pr <- suppressWarnings(cor.test(base$objective_score, base$legacy_risk_score_aligned, method = "pearson"))
obj_group <- ifelse(base$objective_score >= median(base$objective_score), "High risk", "Low risk")
leg_group <- ifelse(base$legacy_risk_score_aligned >= median(base$legacy_risk_score_aligned), "High risk", "Low risk")
tab <- table(factor(obj_group, levels = c("Low risk", "High risk")), factor(leg_group, levels = c("Low risk", "High risk")))
observed_agreement <- sum(diag(tab)) / sum(tab)
expected_agreement <- sum(rowSums(tab) * colSums(tab)) / sum(tab)^2
kappa <- (observed_agreement - expected_agreement) / (1 - expected_agreement)
legacy13 <- c("CD79A", "CD79B", "MS4A1", "IGHM", "BLK", "FCRL5", "TNFRSF17", "MZB1", "JCHAIN", "DERL3", "IGLL5", "IGKC", "CD22")
legacy4 <- c("MS4A1", "IGHM", "BLK", "JCHAIN")
legacy_rows <- rbind(
  data.frame(metric = "objective_score_definition", value = "mean cross-fitted OOF Cox linear predictor across 20 repeats", stringsAsFactors = FALSE),
  data.frame(metric = "legacy_raw_cox_beta", value = legacy_beta, stringsAsFactors = FALSE),
  data.frame(metric = "legacy_risk_alignment_multiplier", value = legacy_transform, stringsAsFactors = FALSE),
  data.frame(metric = "spearman_rho", value = legacy_sp$spearman_rho, stringsAsFactors = FALSE),
  data.frame(metric = "spearman_p_value", value = legacy_sp$p_value, stringsAsFactors = FALSE),
  data.frame(metric = "pearson_r", value = unname(legacy_pr$estimate), stringsAsFactors = FALSE),
  data.frame(metric = "pearson_p_value", value = legacy_pr$p.value, stringsAsFactors = FALSE),
  data.frame(metric = "median_high_low_concordance", value = observed_agreement, stringsAsFactors = FALSE),
  data.frame(metric = "cohen_kappa", value = kappa, stringsAsFactors = FALSE),
  data.frame(metric = "final_model_gene_count", value = length(final_nonzero), stringsAsFactors = FALSE),
  data.frame(metric = "final_model_overlap_legacy_F01_13", value = length(intersect(names(final_nonzero), legacy13)), stringsAsFactors = FALSE),
  data.frame(metric = "final_model_overlap_legacy_BIES_4", value = length(intersect(names(final_nonzero), legacy4)), stringsAsFactors = FALSE)
)
write_tsv(legacy_rows, file.path(results_dir, "OBJECTIVE_VS_LEGACY.tsv"))
write_tsv(as.data.frame.matrix(tab), file.path(results_dir, "OBJECTIVE_VS_LEGACY_MEDIAN_GROUP_CROSSTAB.tsv"))

# Biological concordance: two independent frozen B-cell anchors, no constructed composite.
traits <- read.csv(file.path(root_dir, "results/02_WGCNA/trait_matrix/trait_matrix.csv"), check.names = FALSE, stringsAsFactors = FALSE)
trait_id <- traits$sample_id
base$B_cell_naive <- traits$B_cell_naive[match(base$sample_id, trait_id)]
base$B_cell_memory <- traits$B_cell_memory[match(base$sample_id, trait_id)]
base$Plasma_cell <- traits$Plasma_cell[match(base$sample_id, trait_id)]
wgcna <- readRDS(file.path(root_dir, "results/02_WGCNA/network/wgcna_results.rds"))
if (!"MEyellow" %in% colnames(wgcna$MEs)) stop("MEyellow is absent from locked WGCNA object.")
base$MEyellow <- wgcna$MEs[match(base$sample_id, rownames(wgcna$MEs)), "MEyellow"]
base$CD79A <- as.numeric(vst["CD79A", base$sample_id])
base$MS4A1 <- as.numeric(vst["MS4A1", base$sample_id])

tls21 <- c("CCL2", "CCL3", "CCL4", "CCL5", "CCL8", "CCL18", "CCL19", "CCL21", "CXCL9", "CXCL10", "CXCL11", "CXCL13", "MS4A1", "CD79B", "IGHM", "IGHG1", "IGHG3", "IGKC", "JCHAIN", "MZB1", "CD38")
zmean <- function(gene_set) {
  found <- intersect(gene_set, rownames(vst))
  if (!length(found)) return(rep(NA_real_, nrow(base)))
  zz <- t(apply(vst[found, base$sample_id, drop = FALSE], 1L, function(z) as.numeric(scale(z))))
  colMeans(zz, na.rm = TRUE)
}
tls_overlap <- intersect(tls21, names(final_nonzero))
tls_overlap_free <- setdiff(tls21, tls_overlap)
base$TLS21 <- zmean(tls21)
base$TLS_overlap_free_objective <- zmean(tls_overlap_free)
base$IKZF1 <- as.numeric(vst["IKZF1", base$sample_id])
base$LymphHot <- as.integer(base$CD79A > median(base$CD79A) & base$IKZF1 > median(base$IKZF1))

bio <- do.call(rbind, list(
  spearman_row(base$objective_score, base$CD79A, "CD79A", "descriptive"),
  spearman_row(base$objective_score, base$MS4A1, "MS4A1", "descriptive"),
  spearman_row(base$objective_score, base$MEyellow, "Yellow module eigengene", "descriptive"),
  spearman_row(base$objective_score, base$B_cell_naive, "B_cell_naive", "negative (prespecified anchor)"),
  spearman_row(base$objective_score, base$B_cell_memory, "B_cell_memory", "negative (prespecified anchor)"),
  spearman_row(base$objective_score, base$Plasma_cell, "Plasma_cell", "secondary descriptive only"),
  spearman_row(base$objective_score, base$TLS21, "TLS21", "descriptive; not external validation"),
  spearman_row(base$objective_score, base$TLS_overlap_free_objective, "TLS_overlap_free_objective", "descriptive; not external validation"),
  spearman_row(base$objective_score, base$LymphHot, "LymphHot", "descriptive")
))
write_tsv(bio, file.path(results_dir, "BIOLOGICAL_CONCORDANCE.tsv"))
anchor_naive <- bio$spearman_rho[bio$measure == "B_cell_naive"]
anchor_memory <- bio$spearman_rho[bio$measure == "B_cell_memory"]
axis_ok <- isTRUE(anchor_naive < 0) && isTRUE(anchor_memory < 0)
write_tsv(data.frame(
  criterion = c("B_cell_naive_rho", "B_cell_memory_rho", "B_CELL_AXIS_CONCORDANCE"),
  value = c(anchor_naive, anchor_memory, axis_ok),
  rule = c("must be < 0", "must be < 0", "TRUE only if both anchors are negative"),
  stringsAsFactors = FALSE
), file.path(results_dir, "B_CELL_AXIS_CONCORDANCE.tsv"))
write_tsv(data.frame(
  TLS21_original_gene_count = length(tls21), TLS21_genes_present_in_locked_VST = length(intersect(tls21, rownames(vst))),
  objective_final_model_overlap_gene_count = length(tls_overlap), objective_final_model_overlap_genes = paste(tls_overlap, collapse = ","),
  overlap_free_gene_count = length(tls_overlap_free), overlap_free_genes = paste(tls_overlap_free, collapse = ","),
  stringsAsFactors = FALSE
), file.path(results_dir, "TLS_OVERLAP_FREE_OBJECTIVE_AUDIT.tsv"))

# Descriptive TCGA survival re-evaluation using the locked, post-CV full-data score.
surv_desc <- surv
surv_desc$objective_score <- final_score[match(surv_desc$sample_id, names(final_score))]
feat <- read.csv(file.path(root_dir, "results/04_ML/features/feature_matrix.csv"), check.names = FALSE, stringsAsFactors = FALSE)
surv_desc$feature_sample15 <- substr(surv_desc$sample_id, 1L, 15L)
surv_desc$ImmuneScore <- feat$ImmuneScore[match(surv_desc$feature_sample15, feat$sample_id)]
surv_desc$StromalScore <- feat$StromalScore[match(surv_desc$feature_sample15, feat$sample_id)]

se <- readRDS(file.path(root_dir, "TCGA_HNSC/TCGA_HNSC_STAR_counts_SE.rds"))
clin <- as.data.frame(SummarizedExperiment::colData(se), stringsAsFactors = FALSE)
clin$sample15 <- substr(rownames(clin), 1L, 15L)
clin$sample12 <- substr(rownames(clin), 1L, 12L)
clin$OS_time <- pmax(clin$days_to_death, clin$days_to_last_follow_up, na.rm = TRUE) / 30.44
clin$OS_status <- as.integer(clin$vital_status == "Dead")
clin$stage_34 <- ifelse(grepl("Stage I$|Stage IA|Stage IB|Stage II$|Stage IIA|Stage IIB", clin$ajcc_pathologic_stage, ignore.case = TRUE), 0L,
  ifelse(grepl("Stage III|Stage IV", clin$ajcc_pathologic_stage, ignore.case = TRUE), 1L, NA_integer_))
clin$subsite <- ifelse(grepl("Tongue|Floor of mouth|Mouth, NOS|Cheek|Gum|Lip|Alveolar|Overlapping lesion", clin$tissue_or_organ_of_origin, ignore.case = TRUE), "OralCavity",
  ifelse(grepl("Tonsil|Base of tongue|Oropharynx", clin$tissue_or_organ_of_origin, ignore.case = TRUE), "Oropharynx",
  ifelse(grepl("Larynx|Hypopharynx", clin$tissue_or_organ_of_origin, ignore.case = TRUE), "Larynx_Hypopharynx", "Other_Unknown")))
hpv <- read.csv(file.path(root_dir, "TCGA_HNSC/TCGA_HNSC_HPV_status.csv"), skip = 1L, stringsAsFactors = FALSE)
hpv$sample12 <- substr(as.character(hpv[[1]]), 1L, 12L)
hpv_val <- tolower(as.character(hpv[[2]]))
hpv$HPV3 <- ifelse(hpv_val == "positive", "HPV_pos", ifelse(hpv_val == "negative", "HPV_neg", "HPV_unknown"))
clin$HPV3 <- hpv$HPV3[match(clin$sample12, hpv$sample12)]
clin$HPV3[is.na(clin$HPV3)] <- "HPV_unknown"
clinical_small <- clin[, c("sample15", "age_at_index", "stage_34", "subsite", "HPV3"), drop = FALSE]
surv_desc$sample15 <- substr(surv_desc$sample_id, 1L, 15L)
surv_desc <- merge(surv_desc, clinical_small, by = "sample15", all.x = TRUE, sort = FALSE)
surv_desc <- surv_desc[match(surv$sample_id, surv_desc$sample_id), , drop = FALSE]
tx <- read.delim(file.path(root_dir, "reports/TCGA_TREATMENT_PATIENT_LEVEL_PROVENANCE.tsv"), check.names = FALSE, stringsAsFactors = FALSE)
surv_desc$has_surgery <- tx$surgery_binary[match(substr(surv_desc$sample_id, 1L, 12L), tx$patient_id)]
if (sum(!is.na(surv_desc$has_surgery)) != 434L) stop("Locked unknown-aware treatment provenance mismatch.")
surv_desc$HPV3 <- factor(surv_desc$HPV3, levels = c("HPV_neg", "HPV_pos", "HPV_unknown"))
surv_desc$subsite <- factor(surv_desc$subsite, levels = c("OralCavity", "Oropharynx", "Larynx_Hypopharynx", "Other_Unknown"))
survival_rows <- rbind(
  cox_per_sd(surv_desc, ""),
  cox_per_sd(surv_desc, "ImmuneScore"),
  cox_per_sd(surv_desc, "ImmuneScore + age_at_index + stage_34"),
  cox_per_sd(surv_desc, "ImmuneScore + age_at_index + stage_34 + HPV3 + subsite + has_surgery + StromalScore")
)
survival_rows$model <- c("M1: univariable", "M2: + ImmuneScore", "M3: + ImmuneScore + age + stage", "M4: + HPV + subsite + corrected surgery + StromalScore")
write_tsv(survival_rows, file.path(results_dir, "OBJECTIVE_SCORE_TCGA_SURVIVAL_REEVALUATION.tsv"))
km_group <- ifelse(surv_desc$objective_score > median(surv_desc$objective_score), "High risk", "Low risk")
km_fit <- survival::survdiff(survival::Surv(surv_desc$OS_time, surv_desc$OS_status) ~ km_group)
km_p <- 1 - stats::pchisq(km_fit$chisq, df = 1L)
write_tsv(data.frame(
  split = "median; high if score > median", n = nrow(surv_desc), events = sum(surv_desc$OS_status),
  high_risk_n = sum(km_group == "High risk"), low_risk_n = sum(km_group == "Low risk"),
  logrank_chisq = km_fit$chisq, logrank_p_value = km_p, stringsAsFactors = FALSE
), file.path(results_dir, "OBJECTIVE_SCORE_TCGA_KM_MEDIAN_SPLIT.tsv"))

# External-cohort coverage audit. A score is calculated only if every final-model
# gene is available; partial and proxy coverage are reported but not relabelled as validation.
available_symbols <- function(cohort) {
  if (cohort == "GSE159067") {
    z <- read.table(gzfile(file.path(root_dir, "GSE159067_IHN_log2cpm_data.txt.gz")), header = TRUE, sep = "\t", row.names = 1L, check.names = FALSE)
    return(unique(rownames(z)))
  }
  suppressPackageStartupMessages(library(GEOquery))
  file <- if (cohort == "GSE41613") "GSE41613_series_matrix.txt.gz" else "GSE65858_series_matrix.txt.gz"
  eset <- GEOquery::getGEO(filename = file.path(root_dir, file), GSEMatrix = TRUE, AnnotGPL = FALSE, getGPL = FALSE)
  if (is.list(eset)) eset <- eset[[1]]
  fd <- Biobase::fData(eset)
  symbol_col <- grep("symbol|gene.*name|gene.*symbol", colnames(fd), ignore.case = TRUE, value = TRUE)[1]
  if (!is.na(symbol_col)) {
    syms <- as.character(fd[[symbol_col]])
    syms <- unlist(strsplit(syms, " /// |//|;|,", perl = TRUE), use.names = FALSE)
    return(unique(trimws(syms[nzchar(trimws(syms))])))
  }
  ids <- rownames(Biobase::exprs(eset))
  if (cohort == "GSE41613") {
    suppressPackageStartupMessages({ library(AnnotationDbi); library(hgu133plus2.db) })
    return(unique(na.omit(as.character(AnnotationDbi::mapIds(hgu133plus2.db::hgu133plus2.db, keys = ids, column = "SYMBOL", keytype = "PROBEID", multiVals = "first")))))
  }
  suppressPackageStartupMessages({ library(AnnotationDbi); library(illuminaHumanv4.db) })
  unique(na.omit(as.character(AnnotationDbi::mapIds(illuminaHumanv4.db::illuminaHumanv4.db, keys = ids, column = "SYMBOL", keytype = "PROBEID", multiVals = "first"))))
}

external_rows <- lapply(c("GSE41613", "GSE65858", "GSE159067"), function(cohort) {
  syms <- tryCatch(available_symbols(cohort), error = function(e) structure(character(), error_message = conditionMessage(e)))
  found <- intersect(names(final_nonzero), syms)
  coverage <- 100 * length(found) / length(final_nonzero)
  status <- if (length(found) == length(final_nonzero)) "FULL" else if (length(found) >= 2L) "PARTIAL" else if (length(found) == 1L) "PROXY" else "NOT EVALUABLE"
  data.frame(
    cohort = cohort, required_genes = length(final_nonzero), available_genes = length(found), coverage_percent = coverage,
    status = status, score_analysis = if (status == "FULL") "Eligible for full score only" else "Not run: incomplete coverage is not full validation",
    available_gene_symbols = paste(found, collapse = ","), missing_gene_symbols = paste(setdiff(names(final_nonzero), found), collapse = ","),
    notes = if (!is.null(attr(syms, "error_message"))) attr(syms, "error_message") else "Platform-level identifier audit; no alias remapping.",
    stringsAsFactors = FALSE
  )
})
write_tsv(do.call(rbind, external_rows), file.path(results_dir, "OBJECTIVE_EXTERNAL_COHORT_COVERAGE.tsv"))

writeLines(capture.output(sessionInfo()), file.path(logs_dir, "sessionInfo_post_primary.txt"))
message("Post-primary objective analyses complete. Final model nonzero genes: ", length(final_nonzero), "; B-cell axis concordance: ", axis_ok)
